-- Migration: Year 3 - Abdominal Surgery (Wall & Hernias) MCQ Bank (COMPLETE: 1-350)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'abdominal-surgery' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Abdominal Wall Anatomy and Incisions
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the outermost layer of the abdominal wall in the midline?', '["Skin", "Camper''s fascia", "Scarpa''s fascia", "Rectus sheath"]', 0, 'Midline anatomy: Skin, subcutaneous fat, then the linea alba. (Schwartz''s Ch. 34)'),
    (v_topic_id, '2: "Scarpa''s Fascia" is a membranous layer that is continuous with which fascia in the perineum?', '["Colles'' fascia", "Camper''s fascia", "Dartos fascia", "None"]', 0, 'Important for understanding fluid spread in trauma/infection. (de Virgilio Ch. 12)'),
    (v_topic_id, '3: The "Arcuate Line" (Line of Douglas) is located roughly halfway between the umbilicus and the ____.', '["Xiphoid", "Pubis", "Anterior Superior Iliac Spine", "None"]', 1, 'Marks where all aponeuroses move anterior to the rectus muscle. (Mont Reid Ch. 8)'),
    (v_topic_id, '4: Below the "Arcuate Line," the posterior rectus sheath is composed of:', '["Internal oblique aponeurosis", "Transversalis fascia only", "External oblique aponeurosis", "None"]', 1, 'All three muscle aponeuroses pass anterior to the rectus here. (Schwartz''s Ch. 34)'),
    (v_topic_id, '5: Which artery is the primary blood supply to the rectus abdominis muscle?', '["Superior and Inferior Epigastric arteries", "Internal Iliac artery", "Femoral artery", "None"]', 0, 'Inferior epigastric is a branch of the external iliac. (de Virgilio Ch. 12)'),
    (v_topic_id, '6: A "Kocher Incision" is a subcostal incision used primarily for:', '["Appendectomy", "Open Cholecystectomy / Biliary surgery", "Splenectomy", "None"]', 1, 'Right subcostal incision. (Mont Reid Ch. 8)'),
    (v_topic_id, '7: A "Pfannenstiel Incision" is a transverse incision commonly used for:', '["Liver transplant", "OB/GYN and Pelvic surgery", "Hernia repair", "None"]', 1, 'Low transverse incision above the pubic symphysis. (Schwartz''s Ch. 34)'),
    (v_topic_id, '8: The "McBurney Incision" for appendectomy is located at a point ____ of the way from the ASIS to the umbilicus.', '["1/4", "1/3", "1/2", "2/3"]', 1, 'Corresponds to McBurney''s point. (de Virgilio Ch. 13)'),
    (v_topic_id, '9: "Midline Laparotomy" provides the best exposure and passes through the:', '["Rectus muscle", "Linea alba", "Internal oblique", "None"]', 1, 'Relatively avascular and allows rapid entry. (Mont Reid Ch. 8)'),
    (v_topic_id, '10: Which nerve is most at risk during a low transverse (Pfannenstiel) incision if the rectus is widely mobilized?', '["Vagus", "Iliohypogastric and Ilioinguinal", "Femoral", "None"]', 1, 'Can cause numbness or pain in the suprapubic area. (Schwartz''s Ch. 34)'),

    -- SECTION 2: Inguinal and Femoral Hernias
    (v_topic_id, '11: An "Indirect Inguinal Hernia" passes ____ to the Inferior Epigastric vessels.', '["Medial", "Lateral", "Posterior", "None"]', 1, 'Enters the deep inguinal ring. (de Virgilio Ch. 12)'),
    (v_topic_id, '12: A "Direct Inguinal Hernia" passes ____ to the Inferior Epigastric vessels.', '["Medial", "Lateral", "Superior", "None"]', 0, 'Occurs through a weakness in Hesselbach''s triangle. (Schwartz''s Ch. 37)'),
    (v_topic_id, '13: "Hesselbach''s Triangle" boundaries are the Rectus sheath, Inferior epigastric vessels, and ____.', '["Femoral vein", "Inguinal ligament", "Spermatic cord", "None"]', 1, 'The site of direct hernias. (Mont Reid Ch. 8)'),
    (v_topic_id, '14: Which type of hernia is most common in BOTH males and females?', '["Direct Inguinal", "Indirect Inguinal", "Femoral", "Umbilical"]', 1, 'Indirect is the overall most common type. (de Virgilio Ch. 12)'),
    (v_topic_id, '15: "Femoral Hernias" pass through the femoral canal, which is ____ to the femoral vein.', '["Lateral", "Medial", "Superior", "None"]', 1, 'Commonly found in older females. (Schwartz''s Ch. 37)'),
    (v_topic_id, '16: Which type of hernia carries the HIGHEST risk of incarceration and strangulation?', '["Direct Inguinal", "Indirect Inguinal", "Femoral", "Umbilical"]', 2, 'Due to the narrow, rigid neck of the femoral canal. (Mont Reid Ch. 8)'),
    (v_topic_id, '17: A "Sliding Hernia" is one where:', '["The hernia moves back and forth", "Part of the hernia sac is formed by an internal organ (e.g., cecum, bladder)", "It slides into the scrotum", "None"]', 1, 'Important to recognize to avoid organ injury during repair. (de Virgilio Ch. 12)'),
    (v_topic_id, '18: "Pantaloon Hernia" refers to the presence of both ____ and ____ hernias simultaneously.', '["Direct and Indirect inguinal", "Inguinal and Femoral", "Bilateral inguinal", "None"]', 0, 'The inferior epigastric vessels form the "crotch" of the pants. (Schwartz''s Ch. 37)'),
    (v_topic_id, '19: The "Internal (Deep) Inguinal Ring" is an opening in which layer?', '["External oblique aponeurosis", "Transversalis fascia", "Internal oblique muscle", "None"]', 1, 'The start of the inguinal canal. (Mont Reid Ch. 8)'),
    (v_topic_id, '20: The "External (Superficial) Inguinal Ring" is an opening in which layer?', '["Transversalis fascia", "External oblique aponeurosis", "Peritoneum", "None"]', 1, 'The end of the inguinal canal. (de Virgilio Ch. 12)'),

    -- SECTION 3: Specialized and Rare Hernias
    (v_topic_id, '21: A "Richter''s Hernia" involves incarceration of:', '["The whole bowel loop", "Only a portion of the bowel wall (antimesenteric border)", "The appendix", "Meckel''s diverticulum"]', 1, 'Can strangulate without causing complete bowel obstruction. (Schwartz''s Ch. 37)'),
    (v_topic_id, '22: A "Littre''s Hernia" is defined by the presence of a ____ in the hernia sac.', '["Meckel''s diverticulum", "Appendix", "Ovary", "Bladder"]', 0, 'Rare but high-yield for boards. (de Virgilio Ch. 12)'),
    (v_topic_id, '23: "Amyand''s Hernia" contains the ____ in the inguinal hernia sac.', '["Bladder", "Appendix", "Sigmoid colon", "None"]', 1, 'Often found during routine repair. (Mont Reid Ch. 8)'),
    (v_topic_id, '24: A "Spigelian Hernia" occurs through the semilunar line at the lateral edge of the:', '["Pectoralis", "Rectus abdominis", "External oblique", "None"]', 1, 'Usually below the umbilicus. (Schwartz''s Ch. 37)'),
    (v_topic_id, '25: "Obturator Hernias" are most common in elderly, thin women and can present with the "Howship-Romberg sign," which is pain in the:', '["Groin", "Medial thigh (exacerbated by leg extension/abduction)", "Back", "None"]', 1, 'Due to compression of the obturator nerve. (de Virgilio Ch. 12)'),
    (v_topic_id, '26: A "Grynfeltt''s Hernia" occurs in the:', '["Superior lumbar triangle", "Inferior lumbar triangle", "Femoral canal", "None"]', 0, 'Triangle bounded by 12th rib, internal oblique, and quadratus lumborum. (Mont Reid Ch. 8)'),
    (v_topic_id, '27: A "Petit''s Hernia" occurs in the:', '["Superior lumbar triangle", "Inferior lumbar triangle (bounded by iliac crest, latissimus dorsi, and external oblique)", "Groin", "None"]', 1, 'The lower lumbar triangle. (Schwartz''s Ch. 37)'),
    (v_topic_id, '28: "Sciatic Hernias" pass through the greater or lesser sciatic foramen and can cause:', '["Bowel obstruction or Sciatica-like pain", "Cough", "Fever", "None"]', 0, 'Very rare and difficult to diagnose. (de Virgilio Ch. 12)'),
    (v_topic_id, '29: An "Umbilical Hernia" in an adult is most commonly caused by:', '["Congenital defect", "Increased intra-abdominal pressure (Obesity, Ascites, Pregnancy)", "Trauma", "None"]', 1, 'Often requires surgical repair due to risk of incarceration. (Mont Reid Ch. 8)'),
    (v_topic_id, '30: "Incisional Hernias" are most likely to occur after which type of surgical site complication?', '["Seroma", "Surgical Site Infection (SSI)", "Hematoma", "None"]', 1, 'Infection weakens the fascial closure. (Schwartz''s Ch. 37)'),

    -- SECTION 4: Hernia Management and Repair Techniques
    (v_topic_id, '31: "Incarcerated" hernia means the contents ____, while "Strangulated" means ____.', '["Are dead; Are stuck", "Cannot be reduced; Blood supply is compromised", "Are stuck; Are bleeding", "None"]', 1, 'Strangulation is a surgical emergency. (de Virgilio Ch. 12)'),
    (v_topic_id, '32: "Tension-Free" hernia repair using mesh (e.g., Lichtenstein) has a lower recurrence rate than primary tissue repairs.', '["True", "False", "Only in women", "None"]', 0, 'Current standard of care for most adult inguinal hernias. (Schwartz''s Ch. 37)'),
    (v_topic_id, '33: A "Bassini Repair" involves suturing the conjoined tendon to the:', '["Cooper''s ligament", "Inguinal ligament (Poupart''s)", "Rectus sheath", "None"]', 1, 'An older, tension-based tissue repair. (Mont Reid Ch. 8)'),
    (v_topic_id, '34: A "McVay (Cooper''s Ligament) Repair" is primarily used to address both inguinal and ____ hernias.', '["Umbilical", "Femoral", "Epigastric", "None"]', 1, 'Sutures the conjoined tendon to Cooper''s ligament. (de Virgilio Ch. 12)'),
    (v_topic_id, '35: During laparoscopic hernia repair (TAPP or TEP), the "Triangle of Doom" contains which vessels?', '["Inferior epigastrics", "External iliac artery and vein", "Femoral nerve", "None"]', 1, 'Bounded by the vas deferens and gonadal vessels. (Schwartz''s Ch. 37)'),
    (v_topic_id, '36: The "Triangle of Pain" in laparoscopic hernia repair contains which nerves?', '["Obturator", "Lateral femoral cutaneous, Genitofemoral (femoral branch)", "Vagus", "None"]', 1, 'Located lateral to the gonadal vessels. (Mont Reid Ch. 8)'),
    (v_topic_id, '37: What is the preferred management for a small, asymptomatic umbilical hernia in a 2-year-old child?', '["Immediate surgery", "Observation (most close spontaneously by age 4-5)", "Mesh repair", "None"]', 1, 'Surgery is delayed unless it persists or is very large. (de Virgilio Ch. 12)'),
    (v_topic_id, '38: "Plug and Patch" repair is a variant of which hernia repair technique?', '["Shouldice", "Lichtenstein", "TAPP", "None"]', 1, 'Uses a cone-shaped mesh plug. (Schwartz''s Ch. 37)'),
    (v_topic_id, '39: Chronic "Post-herniorrhaphy" pain (Inguinodynia) is most commonly caused by injury to which nerve?', '["Femoral", "Ilioinguinal, Iliohypogastric, or Genitofemoral", "Sciatic", "None"]', 1, 'Can be due to nerve entrapment in mesh or sutures. (Mont Reid Ch. 8)'),
    (v_topic_id, '40: For a strangulated hernia with dead bowel, what is the most appropriate management of the mesh?', '["Use mesh anyway", "Avoid synthetic mesh; perform tissue repair or use biologic/absorbable mesh", "Wait 1 week", "None"]', 1, 'Synthetic mesh in an infected/contaminated field has high risk of infection. (de Virgilio Ch. 12)'),

    -- SECTION 5: Abdominal Wall Masses and Other Conditions
    (v_topic_id, '41: A "Desmoid Tumor" of the abdominal wall is a benign but locally aggressive growth associated with:', '["Gardner Syndrome (FAP variant)", "Lynch Syndrome", "Breast cancer", "None"]', 0, 'Does not metastasize but has high recurrence. (Schwartz''s Ch. 34)'),
    (v_topic_id, '42: "Rectus Sheath Hematoma" above the arcuate line is usually contained and due to rupture of the ____ artery.', '["Inferior epigastric", "Superior epigastric", "Femoral", "None"]', 1, 'Often follows forceful coughing or trauma in patients on anticoagulants. (de Virgilio Ch. 12)'),
    (v_topic_id, '43: "Sister Mary Joseph Nodule" refers to a palpable nodule at the umbilicus that represents:', '["A benign cyst", "Metastatic intra-abdominal malignancy (often gastric/pancreatic)", "A hernia", "None"]', 1, 'Named after a nurse who noticed the association. (Mont Reid Ch. 13)'),
    (v_topic_id, '44: "Rectus Diastasis" (Diastasis Recti) is characterized by:', '["A true hernia sac", "Separation of the rectus muscles without a fascial defect", "A muscle tear", "None"]', 1, 'Presents as a bulge when the patient raises their head; surgery is cosmetic. (Schwartz''s Ch. 34)'),
    (v_topic_id, '45: "Omphalocele" differs from "Gastroschisis" because the bowel is:', '["Covered by a peritoneal sac", "Open to the air", "In the chest", "None"]', 0, 'Omphalocele is at the umbilicus and has a sac. (de Virgilio Ch. 53)'),
    (v_topic_id, '46: "Gastroschisis" typically occurs to the ____ of the umbilicus.', '["Left", "Right", "Top", "Bottom"]', 1, 'No sac; bowel is exposed to amniotic fluid (causes "peel"). (Mont Reid Ch. 14)'),
    (v_topic_id, '47: "Abdominal Compartment Syndrome" is defined by an intra-abdominal pressure (IAP) > ____ mmHg with new organ dysfunction.', '["5", "12", "20", "None"]', 2, 'Measured via bladder pressure. (Schwartz''s Ch. 5)'),
    (v_topic_id, '48: The definitive treatment for Abdominal Compartment Syndrome is:', '["Aggressive diuresis", "Decompressive laparotomy (leaving the abdomen open)", "Foley catheter", "None"]', 1, 'Relieves pressure to restore organ perfusion. (de Virgilio Ch. 4)'),
    (v_topic_id, '49: "Endventration" is a complication of laparotomy where the fascia ____ but the skin ____.', '["Heals; Tears", "Dehisces (opens); Remains intact", "Tears; Tears", "None"]', 1, 'Essentially an acute incisional hernia. (Mont Reid Ch. 1)'),
    (v_topic_id, '50: "Primary Peritonitis" (SBP) is most common in patients with:', '["Appendicitis", "Cirrhosis with ascites", "Stomach ulcer", "None"]', 1, 'Usually monomicrobial (E. coli). (Schwartz''s Ch. 6)');

    -- Batch 2: 51-150 (Deep Dive Hernia & Wall)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Secondary Peritonitis" is caused by:', '["Liver failure", "Perforation or infection of an intra-abdominal organ (e.g., ruptured appendix)", "TB", "None"]', 1, 'Usually polymicrobial. (de Virgilio Ch. 6)'),
    (v_topic_id, '52: "Tertiary Peritonitis" refers to:', '["First infection", "Persistent or recurrent peritonitis after treatment of secondary peritonitis", "TB", "None"]', 1, 'Often involves nosocomial or fungal organisms. (Mont Reid Ch. 1)'),
    (v_topic_id, '53: An "Epigastric Hernia" occurs in the midline between the ____ and umbilicus.', '["Pubis", "Xiphoid", "Nipple", "None"]', 1, 'Occurs through a defect in the linea alba. (Schwartz''s Ch. 37)'),
    (v_topic_id, '54: "Petit''s Triangle" (Inferior Lumbar) is bounded by the iliac crest, external oblique, and ____.', '["Rectus", "Latissimus dorsi", "Trapezius", "None"]', 1, 'Site of rare lumbar hernias. (de Virgilio Ch. 12)'),
    (v_topic_id, '55: "Grynfeltt''s Triangle" (Superior Lumbar) is bounded by the 12th rib, internal oblique, and ____.', '["Quadratus lumborum", "Psoas", "Rectus", "None"]', 0, 'Larger and more common site for lumbar hernias. (Mont Reid Ch. 8)'),
    (v_topic_id, '56: A "Velpeau Hernia" is an inguinal hernia that is located ____ the femoral vessels.', '["In front of", "Behind", "Medial to", "None"]', 0, 'Another name for pre-vascular femoral hernia. (Schwartz''s Ch. 37)'),
    (v_topic_id, '57: "Gimbernat''s Ligament" is another name for the ____ ligament.', '["Inguinal", "Lacunar", "Cooper''s", "None"]', 1, 'Forms the medial border of the femoral canal. (de Virgilio Ch. 12)'),
    (v_topic_id, '58: "Poupart''s Ligament" is another name for the ____ ligament.', '["Lacunar", "Inguinal", "Pectineal", "None"]', 1, 'Formed by the external oblique aponeurosis. (Mont Reid Ch. 8)'),
    (v_topic_id, '59: "Cooper''s Ligament" is another name for the ____ ligament.', '["Inguinal", "Pectineal", "Lacunar", "None"]', 1, 'Attached to the pectineal line of the pubis. (Schwartz''s Ch. 37)'),
    (v_topic_id, '60: The "Iliopubic Tract" is a thickened band of ____ fascia.', '["Camper''s", "Transversalis", "Scarpa''s", "None"]', 1, 'Crucial landmark in laparoscopic hernia repair. (de Virgilio Ch. 12)'),
    (v_topic_id, '61: In "TAPP" laparoscopic repair, the peritoneum is ____.', '["Not touched", "Opened (Trans-Abdominal Pre-Peritoneal)", "Removed", "None"]', 1, 'Entry is into the peritoneal cavity first. (Mont Reid Ch. 8)'),
    (v_topic_id, '62: In "TEP" laparoscopic repair, the peritoneal cavity is ____.', '["Opened", "Never entered (Totally Extra-Peritoneal)", "Bypassed", "None"]', 1, 'Dissection is entirely in the pre-peritoneal space. (Schwartz''s Ch. 37)'),
    (v_topic_id, '63: Which laparoscopic approach (TEP or TAPP) is preferred for a patient with previous lower abdominal surgery?', '["TEP", "TAPP (allows visualization of adhesions)", "Neither", "None"]', 1, 'Allows safer entry and adhesiolysis. (de Virgilio Ch. 12)'),
    (v_topic_id, '64: "Nyhus Classification" Type I is an indirect hernia in a/an ____.', '["Adult", "Infant/Child (Normal ring)", "Obese patient", "None"]', 1, 'Simple indirect hernia. (Mont Reid Ch. 8)'),
    (v_topic_id, '65: "Nyhus Classification" Type III includes which hernias?', '["Direct, Femoral, and Large indirect hernias", "Type I", "Type II", "None"]', 0, 'Reflects posterior wall defects. (Schwartz''s Ch. 37)'),
    (v_topic_id, '66: A "Recurrent" hernia is classified as Nyhus Type ____.', '["I", "II", "III", "IV"]', 3, 'Includes recurrent inguinal or femoral. (de Virgilio Ch. 12)'),
    (v_topic_id, '67: What is the nerve most commonly injured in OPEN inguinal hernia repair?', '["Femoral", "Ilioinguinal", "Obturator", "None"]', 1, 'Located on the surface of the spermatic cord/cremaster muscle. (Mont Reid Ch. 8)'),
    (v_topic_id, '68: Injury to the "Genitofemoral" nerve (genital branch) leads to loss of the ____ reflex.', '["Gag", "Cremasteric", "Patellar", "None"]', 1, 'Also causes scrotal/labial numbness. (Schwartz''s Ch. 37)'),
    (v_topic_id, '69: Injury to the "Lateral Femoral Cutaneous" nerve leads to pain/numbness in the ____ thigh.', '["Medial", "Lateral", "Posterior", "None"]', 1, 'Known as Meralgia Paresthetica. (de Virgilio Ch. 12)'),
    (v_topic_id, '70: "Ischemic Orchitis" after hernia repair is due to thrombosis of the ____.', '["Vas deferens", "Pampiniform plexus of veins", "Testicular artery", "None"]', 1, 'Leads to testicular atrophy but rarely necrosis (due to collaterals). (Mont Reid Ch. 8)'),
    (v_topic_id, '71: "Hydrocele" is a collection of fluid within the ____.', '["Spermatic cord", "Tunica vaginalis", "Bladder", "None"]', 1, 'Transilluminates on exam. (Schwartz''s Ch. 37)'),
    (v_topic_id, '72: "Varicocele" is a dilation of the pampiniform plexus, most common on the ____ side.', '["Right", "Left", "Both equally", "None"]', 1, 'Due to the left renal vein anatomy ("bag of worms"). (de Virgilio Ch. 12)'),
    (v_topic_id, '73: A sudden onset RIGHT-sided varicocele in an adult should prompt evaluation for:', '["Heart failure", "Renal Cell Carcinoma (blocking the IVC)", "Hernia", "None"]', 1, 'Right spermatic vein drains directly into the IVC. (Mont Reid Ch. 13)'),
    (v_topic_id, '74: "Torsion of the Testis" is a surgical emergency; what is the "golden period" for salvage?', '["1 hour", "6 hours", "24 hours", "None"]', 1, 'Salvage rate drops significantly after 6h of ischemia. (Schwartz''s Ch. 37)'),
    (v_topic_id, '75: "Bell-Clapper Deformity" is a predisposing factor for:', '["Hernia", "Testicular Torsion", "Hydrocele", "None"]', 1, 'Abnormal attachment of the tunica vaginalis. (de Virgilio Ch. 12)'),
    (v_topic_id, '76: "Phren''s Sign" (relief of pain with scrotal elevation) is classically positive in ____ and negative in ____.', '["Torsion; Epididymitis", "Epididymitis; Torsion", "Hernia; Hydrocele", "None"]', 1, 'Used to help distinguish the two, though unreliable. (Mont Reid Ch. 13)'),
    (v_topic_id, '77: "Fournier''s Gangrene" is a necrotizing fasciitis of the ____.', '["Leg", "Perineum / Scrotum", "Abdominal wall", "None"]', 1, 'Requires emergent wide debridement. (Schwartz''s Ch. 6)'),
    (v_topic_id, '78: "Paraphimosis" is a condition where:', '["The foreskin cannot be retracted", "The retracted foreskin cannot be returned to its normal position", "The penis is bent", "None"]', 1, 'Urologic emergency due to risk of glans ischemia. (de Virgilio Ch. 1)'),
    (v_topic_id, '79: "Phimosis" is when:', '["The foreskin is too short", "The foreskin cannot be retracted over the glans", "The penis is painful", "None"]', 1, 'Treated with circumcision if symptomatic. (Mont Reid Ch. 1)'),
    (v_topic_id, '80: "Priapism" is a prolonged, painful erection lasting > ____ hours.', '["1", "4", "24", "None"]', 1, 'Associated with sickle cell disease and certain meds. (Schwartz''s Ch. 37)'),
    (v_topic_id, '81: "Caput Medusae" (dilated veins around the umbilicus) is a sign of:', '["Heart failure", "Portal Hypertension (Cirrhosis)", "Lung cancer", "None"]', 1, 'Due to recanalization of the umbilical vein. (de Virgilio Ch. 14)'),
    (v_topic_id, '82: "Cruveilhier-Baumgarten" murmur is heard over the umbilicus in cases of:', '["Aortic aneurysm", "Portal Hypertension", "Gallstones", "None"]', 1, 'Due to high flow in the umbilical vein. (Mont Reid Ch. 13)'),
    (v_topic_id, '83: "Stoma" location: The ideal site for a stoma is through the ____ muscle.', '["External oblique", "Rectus abdominis", "Internal oblique", "None"]', 1, 'Reduces the risk of parastomal hernia. (Schwartz''s Ch. 37)'),
    (v_topic_id, '84: "Parastomal Hernia" is a type of ____ hernia.', '["Umbilical", "Incisional", "Inguinal", "None"]', 1, 'Occurs adjacent to a stoma. (de Virgilio Ch. 12)'),
    (v_topic_id, '85: "Fascial" closure after laparotomy: The recommended "suture-to-wound length" ratio is:', '["1:1", "2:1", "4:1", "10:1"]', 2, 'Reduces the risk of incisional hernia. (Mont Reid Ch. 8)'),
    (v_topic_id, '86: "Retention" sutures are used in:', '["Low risk closures", "High risk patients (obese, malnourished) to prevent dehiscence", "Kids", "None"]', 1, 'Pass through all layers of the abdominal wall. (Schwartz''s Ch. 34)'),
    (v_topic_id, '87: "Burst Abdomen" is another term for ____.', '["Dehiscence with evisceration", "Gas", "Ileus", "None"]', 0, 'Surgical emergency. (de Virgilio Ch. 1)'),
    (v_topic_id, '88: "Wound" classification: A "Clean-Contaminated" wound involves:', '["No entry into gut", "Controlled entry into the respiratory, GI, or GU tract", "Active infection", "None"]', 1, 'e.g., Elective cholecystectomy. (Mont Reid Ch. 1)'),
    (v_topic_id, '89: "Wound" classification: A "Dirty" wound involves:', '["Spillage", "Old traumatic wound or clinical infection/perforation", "Bile", "None"]', 1, 'e.g., Ruptured appendix. (Schwartz''s Ch. 6)'),
    (v_topic_id, '90: "Antibiotic Prophylaxis" for surgery should be given within ____ hour(s) of incision.', '["1", "4", "24", "None"]', 0, 'Ensures peak tissue levels during surgery. (de Virgilio Ch. 1)'),
    (v_topic_id, '91: "Cefazolin" (Ancef) is the most common prophylactic antibiotic because it targets ____.', '["Gram-negatives", "Skin flora (Staph/Strep)", "Anaerobes", "None"]', 1, 'Gram-positive coverage. (Mont Reid Ch. 1)'),
    (v_topic_id, '92: For "Colorectal" surgery, prophylaxis must also include coverage for ____.', '["Viruses", "Anaerobes and Gram-negatives", "Fungi", "None"]', 1, 'e.g., Cefoxitin or Cefazolin + Metronidazole. (Schwartz''s Ch. 6)'),
    (v_topic_id, '93: "Biofilm" formation is a major reason why ____ mesh is difficult to salvage after infection.', '["Biologic", "Synthetic (Prosthetic)", "Absorbable", "None"]', 1, 'Usually requires complete removal of the mesh. (de Virgilio Ch. 12)'),
    (v_topic_id, '94: "Lichtenstein" repair is an ____ mesh repair.', '["Laparoscopic", "Open (Inlay/Onlay)", "Robot", "None"]', 1, 'The "gold standard" open repair. (Mont Reid Ch. 8)'),
    (v_topic_id, '95: "Shouldice" repair is an open ____ repair.', '["Mesh", "Tissue (multi-layered imbrication)", "Bipolar", "None"]', 1, 'Lowest recurrence rate among tissue repairs. (Schwartz''s Ch. 37)'),
    (v_topic_id, '96: "Grynfeltt" triangle is ____ than "Petit''s" triangle.', '["Smaller", "Larger", "Lower", "None"]', 1, 'Superior lumbar triangle. (de Virgilio Ch. 12)'),
    (v_topic_id, '97: "Spigelian" hernia is also called "hernia ____."', '["In the midline", "Spontanea", "Lumbar", "None"]', 1, 'Named after Adriaan van den Spiegel. (Mont Reid Ch. 8)'),
